package com.together.couple;
import android.app.NotificationManager;import android.content.*;import java.net.*;
public class CallDeclineReceiver extends BroadcastReceiver {
@Override public void onReceive(Context context,Intent intent){String id=intent.getStringExtra("id");if(id==null)return;try{java.util.UUID.fromString(id);}catch(Exception error){return;}((NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(id.hashCode());var prefs=context.getSharedPreferences("calls",Context.MODE_PRIVATE);String url=prefs.getString("url",""),token=prefs.getString("token","");if(!url.startsWith("https://")||token.isEmpty())return;var pending=goAsync();new Thread(()->{HttpURLConnection connection=null;try{connection=(HttpURLConnection)new URL(url+"/api/communication/calls/"+id+"/decline").openConnection();connection.setConnectTimeout(5000);connection.setReadTimeout(5000);connection.setRequestMethod("POST");connection.setRequestProperty("Authorization","Bearer "+token);connection.setRequestProperty("Content-Type","application/json");connection.setDoOutput(true);try(var stream=connection.getOutputStream()){stream.write("{}".getBytes(java.nio.charset.StandardCharsets.UTF_8));}connection.getResponseCode();}catch(Exception ignored){}finally{if(connection!=null)connection.disconnect();pending.finish();}}).start();}
}